class Solution {
    int countSoldiers(vector<vector<int>>& mat, int row) {
        int n = mat[0].size();
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (mat[row][mid] == 0)
                hi = mid;
            else
                lo = mid + 1;
        }
        return lo;
    }
public:
    vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
        int m = mat.size();
        priority_queue<pair<int,int>> pq;
        for (int i = 0; i < m; i++) {
            int cnt = countSoldiers(mat, i);
            pq.push({cnt, i});
            if ((int)pq.size() > k)
                pq.pop();
        }
        vector<int> result(k);
        for (int i = k - 1; i >= 0; i--) {
            result[i] = pq.top().second;
            pq.pop();
        }
        return result;
    }
};
